window.AUTH=window.AUTH||{};window.AUTH["25-5930"]={"d":"25-5930","id":"2026/25-5930","n":"Maxwell v. Dinis","briefs":[{"k":"petitioner","label":"Brief of petitioner William Maxwell","date":"2026-08-05","url":"https://www.supremecourt.gov/DocketPDF/25/25-5930/418167/20260805123041240_25-5930%20opening%20brief%20final_PDFA.pdf","side":"pet","n":131},{"k":"respondent","label":"Brief for the respondent Sandra Dinis, Acting Warden supporting vacatur","date":"2026-08-05","url":"https://www.supremecourt.gov/DocketPDF/25/25-5930/418232/20260805174545194_25-5930UnitedStates.pdf","side":"res","n":144},{"k":"reply","label":"Reply of petitioner William Maxwell","date":"2026-10-19","url":"https://www.supremecourt.gov/DocketPDF/25/25-5930/429966/20261019143126980_25-5930MaxwellReplyBrief.pdf","side":"pet","n":65}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"by":{"0":"8"}},{"t":"case","label":"Alqsous v. Emmerich","cite":"2026 WL 125691","y":2026,"court":"W.D. Wis. Jan. 16","by":{"0":"36"}},{"t":"case","label":"Andreozzi v. Manager, Residential Reentry Management Seattle","cite":"2023 WL 7156173","y":2023,"court":"W.D. Wash. Oct. 31","by":{"0":"35"}},{"t":"case","label":"Arketa v. Wilson","cite":"373 F.2d 582","y":1967,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/373/582/","by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"free [a petitioner] from prison custody, as distinguished from releasing him from all custody.","cite":"373 F.2d 582, 584"}]},{"t":"case","label":"Armstrong v. Exceptional Child Center, Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"power of federal courts of equity to enjoin unlawful executive action is subject to express and implied statutory limitations.","cite":"575 U.S. at 327"}]},{"t":"case","label":"Beras v. Johnson","cite":"978 F.3d 246","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/978/246/","by":{"0":"32"}},{"t":"case","label":"Bivens v. Six Unknown Federal Narcotics Agents","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"by":{"0":"11, 13, 30, 38","1":"2, 13, 15, 20","2":"14"},"q":[{"src":"argument","who":"Justice Jackson","text":"It seems to me the circumstances here are very narrow, whether a prisoner who is claiming that he's being unlawfully detained because he's entitled to placement in a halfway house if his good-time credits had been calculated properly, that under those circumstances, narrowly, is he able to bring that claim in habeas or, as the Fifth Circuit said, is that the kind of claim that would -- that has to be brought as a Bivens claim?"},{"src":"argument","who":"Ms. Hansford","text":"There's a circuit split where prisoners in two big circuits are told they have to label their requests Bivens claims, which everybody agrees cannot possibly be right."},{"src":"argument","who":"Mr. Barber","text":"Yes, and there's certainly no Bivens claim. Yes."}]},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"by":{"0":"5, 6"},"q":[{"src":"brief","b":0,"text":"no man would be imprisoned contrary to the law of the land.","cite":"553 U.S. 723, 740"},{"src":"brief","b":0,"text":"viewed freedom from unlawful re- straint as a fundamental precept of liberty, and they understood the writ of habeas corpus as a vital instrument to secure that freedom.","cite":"553 U.S. at 739"}]},{"t":"case","label":"Bowe v. United States","cite":"607 U.S. 13","y":2026,"id":"2025/24-5438","sc":1,"by":{"0":"7, 32"}},{"t":"case","label":"Boyce v. Ashcroft","cite":"251 F.3d 911","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/251/911/","by":{"0":"38"}},{"t":"case","label":"Brown v. Davenport","cite":"596 U.S. 118","y":2022,"id":"2021/20-826","sc":1,"by":{"0":"7","1":"17, 19, 39"},"q":[{"src":"brief","b":1,"text":"habeas corpus ad subjiciendum, often called the ‘Great Writ.’","cite":"596 U.S. 118, 128"}]},{"t":"case","label":"Brown-El v. Hall","cite":"8 F.3d 20","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/8/20/","by":{"0":"36"}},{"t":"case","label":"Butler v. United States Parole Commission","cite":"570 F. Supp. 67","y":1983,"court":"M.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./570/67/","by":{"0":"36"}},{"t":"case","label":"Carafas v. LaVallee","cite":"391 U.S. 234","y":1968,"id":"1967/71","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"does not limit the relief * * * to discharge of the applicant from physical custody.","cite":"391 U.S. 234, 239"}]},{"t":"case","label":"Carmona v. United States Bureau of Prisons","cite":"243 F.3d 629","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/243/629/","by":{"0":"32","1":"35"}},{"t":"case","label":"Cheney v. United States District Court for District of Columbia","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"by":{"0":"31","1":"34"},"q":[{"src":"brief","b":0,"text":"drastic and extraordinary remedy reserved for really extraordinary causes.","cite":"542 U.S. 367, 380"}]},{"t":"case","label":"Cisco Systems, Inc. v. Doe I","cite":"146 S. Ct. 1882","y":2026,"id":"2025/24-856","sc":1,"by":{"0":"30"}},{"t":"case","label":"Cofer v. Fleming","cite":"2001 WL 1297687","y":2001,"court":"N.D. Tex. Oct. 11","by":{"0":"36"}},{"t":"case","label":"Coleman v. Tennessee","cite":"97 U.S. 509","y":1878,"id":"scdb/1878-108","sc":1,"by":{"0":"22, 23"}},{"t":"case","label":"Correctional Services Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"by":{"0":"30","1":"20"}},{"t":"case","label":"Cossio v. Air Force Court of Criminal Appeals","cite":"129 F.4th 1013","y":2025,"url":"https://www.courtlistener.com/c/F.4th/129/1013/","by":{"0":"40"}},{"t":"case","label":"Department of Homeland Security v. Thuraissigiam","cite":"591 U.S. 103","y":2020,"id":"2019/19-161","sc":1,"by":{"0":"17"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"by":{"0":"30","1":"33"},"q":[{"src":"brief","b":1,"text":"extraordinary act that places great stress on the separation of powers.","cite":"596 U.S. 482, 491, 497 n.3"}]},{"t":"case","label":"Escoe v. Zerbst","cite":"295 U.S. 490","y":1935,"id":"scdb/1934-133","sc":1,"by":{"0":"23, 24"}},{"t":"case","label":"Falcon v. United States Bureau of Prisons","cite":"52 F.3d 137","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/52/137/","by":{"0":"39"}},{"t":"case","label":"Federal Defenders of New York, Inc. v. Federal Bureau of Prisons","cite":"954 F.3d 118","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/954/118/","by":{"0":"31"}},{"t":"case","label":"Finetti v. Harris","cite":"609 F.2d 594","y":1979,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/609/594/","by":{"0":"24"}},{"t":"case","label":"Fortner v. Eischen","cite":"170 F.4th 655","y":2026,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/170/655/","by":{"0":"30, 37, 39, 40","1":"27, 29","2":"7"},"q":[{"src":"brief","b":0,"text":"detention in a different location with better conditions.","cite":"170 F.4th at 658"},{"src":"brief","b":1,"text":"[t]he relevant statute calls those in prerelease custody ‘prisoners’ who are serving ‘a term of imprisonment.’","cite":"170 F.4th at 658"}]},{"t":"case","label":"Fuller v. Rich","cite":"11 F.3d 61","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/11/61/","by":{"0":"32"}},{"t":"case","label":"Ganim v. Federal Bureau of Prisons","cite":"235 Fed. Appx. 882","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./235/882/","by":{"0":"39"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"by":{"0":"6"},"q":[{"src":"brief","b":0,"text":"the only common-law writ to be explicitly mentioned","cite":"542 U.S. 507, 558"}]},{"t":"case","label":"Hensley v. Municipal Court","cite":"411 U.S. 345","y":1973,"id":"1972/71-1428","sc":1,"by":{"0":"25, 40","1":"30"}},{"t":"case","label":"Hill v. McDonough","cite":"547 U.S. 573","y":2006,"id":"2005/05-8794","sc":1,"by":{"0":"28"}},{"t":"case","label":"Hilton v. Braunskill","cite":"481 U.S. 770","y":1987,"id":"1986/86-108","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"delay[ing] the release of a successful habeas petitioner in order to provide the State an opportunity to correct the constitutional violation found by the court.","cite":"481 U.S. 770, 775"}]},{"t":"case","label":"Jones v. Cunningham","cite":"371 U.S. 236","y":1963,"id":"1962/77","sc":1,"by":{"0":"25, 26, 40","1":"15, 27, 28, 30"},"q":[{"src":"brief","b":1,"text":"[T]he chief use of habeas corpus has been to seek the release of persons held in actual, physical custody in prison or jail,","cite":"371 U.S. 236, 238"},{"src":"brief","b":1,"text":"In England, as in the United States, the chief use of habeas corpus has been to seek the release of persons held in actual, physical custody in prison or jail,","cite":"371 U.S. 236, 238"},{"src":"argument","who":"Mr. Barber","text":"So, if you look at Preiser, Jones against Cunningham, the Court has always made clear that habeas is available when your claim is seeking discharge from actual physical confinement in prison to a different kind of custody, a lower level of custody in Petitioner's terms, but a different kind of custody."}]},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"by":{"0":"7, 12, 18, 19, 27, 28, 32","1":"13, 17-19, 24, 27, 30, 39","2":"5, 7"},"q":[{"src":"brief","b":0,"text":"separate remedial vehicle specifically designed for federal prisoners’ collateral attacks on their sentences.","cite":"599 U.S. 465, 473"},{"src":"brief","b":0,"text":"‘the legality of his detention’ without attacking the validity of his sentence.","cite":"599 U.S. at 475"},{"src":"brief","b":1,"text":"sentence after conviction ‘by a court of competent jurisdiction’ was ‘in itself sufficient cause’ for a prisoner’s continued detention.","cite":"599 U.S. 465, 483"},{"src":"brief","b":1,"text":"‘may be restrained of his or her liberty in violation of the constitution, or of any treaty or law of the United States.’","cite":"599 U.S. at 472"},{"src":"brief","b":2,"text":"‘the legality of his detention’ without attacking the validity of his sentence.","cite":"599 U.S. 465, 475"},{"src":"argument","who":"Mr. Barber","text":"This Court has made clear in Jones against Hendrix and other cases that habeas -- the Suspension Clause version of habeas is that narrow founding-era version."}]},{"t":"case","label":"Joost v. United States Parole Commission","cite":"698 F.2d 418","y":1983,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/698/418/","by":{"0":"24"}},{"t":"case","label":"Justices of Boston Municipal Court v. Lydon","cite":"466 U.S. 294","y":1984,"id":"1983/82-1479","sc":1,"by":{"0":"24"}},{"t":"case","label":"Khalil v. President","cite":"164 F.4th 259","y":2026,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/164/259/","by":{"0":"32"}},{"t":"case","label":"Klein v. Martin","cite":"607 U.S. 213","y":2026,"url":"https://supreme.justia.com/cases/federal/us/607/213/","sc":1,"by":{"0":"7"}},{"t":"case","label":"Kruger v. Erickson","cite":"77 F.3d 1071","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/77/1071/","by":{"0":"39"}},{"t":"case","label":"Mahler v. Eby","cite":"264 U.S. 32","y":1924,"id":"scdb/1923-058","sc":1,"by":{"0":"22"}},{"t":"case","label":"Mandacina v. Entzel","cite":"991 F.3d 758","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/758/","by":{"0":"33"}},{"t":"case","label":"Martin v. Solem","cite":"801 F.2d 324","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/801/324/","by":{"0":"24"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"by":{"0":"32"}},{"t":"case","label":"McDonough v. Smith","cite":"588 U.S. 109","y":2019,"id":"2018/18-485","sc":1,"by":{"0":"29"}},{"t":"case","label":"McMiller v. Carter","cite":"2025 WL 3022385","y":2025,"court":"D. Md. Oct. 29","by":{"0":"31"}},{"t":"case","label":"Melot v. Bergami","cite":"970 F.3d 596","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/970/596/","by":{"0":"11, 30, 37, 38","1":"13, 32"},"q":[{"src":"brief","b":0,"text":"automatically entitle [the prisoner] to accelerated release.","cite":"970 F.3d at 599"},{"src":"brief","b":1,"text":"a habeas petition ‘is the proper vehicle to seek release from custody,’ while a civil rights suit under Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics, 403 U.S. 388 (1971), is the ‘proper vehicle to attack unconstitutional conditions of confinement and prison procedures.’","cite":"970 F.3d 596, 599"}]},{"t":"case","label":"Minnesota v. Murphy","cite":"465 U.S. 420","y":1984,"id":"1983/82-827","sc":1,"by":{"0":"25"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"0":"8"}},{"t":"case","label":"Mont v. United States","cite":"587 U.S. 514","y":2019,"id":"2018/17-8995","sc":1,"by":{"0":"8","1":"31"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"by":{"0":"17"}},{"t":"case","label":"Nance v. Ward","cite":"597 U.S. 159","y":2022,"id":"2021/21-439","sc":1,"by":{"0":"28, 38"},"q":[{"src":"brief","b":0,"text":"an inmate seeks to overturn his death sentence, thus preventing the State from executing him.","cite":"597 U.S. 159, 167"}]},{"t":"case","label":"Nekvasil v. United States","cite":"2022 WL 4115428","y":2022,"court":"W.D. Mich. Sept. 9","by":{"0":"35"}},{"t":"case","label":"Olivier v. City of Brandon","cite":"607 U.S. 552","y":2026,"id":"2025/24-993","sc":1,"by":{"0":"40","1":"21, 25"},"q":[{"src":"brief","b":1,"text":"claims that [a]re really assaults on a prior conviction","cite":"607 U.S. 552, 565"}]},{"t":"case","label":"Ortega v. United States Immigration & Customs Enforcement","cite":"737 F.3d 435","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/737/435/","by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"from every vantage point: privacy, companionship, comfort.","cite":"737 F.3d 435, 439"}]},{"t":"case","label":"Palma-Salazar v. Davis","cite":"677 F.3d 1031","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/677/1031/","by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"immediate release from, or a shortened period of, physical imprisonment, i.e., placement on parole or in a parole-like custodial setting.","cite":"677 F.3d 1031, 1037 n.2"}]},{"t":"case","label":"Peyton v. Rowe","cite":"391 U.S. 54","y":1968,"id":"1967/802","sc":1,"by":{"0":"23","1":"17, 28"},"q":[{"src":"brief","b":0,"text":"though he would not be released if he prevailed,","cite":"391 U.S. 54, 67"}]},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"by":{"0":"5, 13, 15, 17, 25-27, 33, 34, 36","1":"3, 14, 17, 18, 21-23, 25, 28, 30, 39","2":"5, 6, 10"},"q":[{"src":"brief","b":0,"text":"traditional function of the writ is to secure release from illegal custody.","cite":"411 U.S. at 484"},{"src":"brief","b":0,"text":"fell squarely within th[e] traditional scope of habeas corpus.","cite":"411 U.S. at 487"},{"src":"brief","b":1,"text":"to obtain release from such confinement.","cite":"411 U.S. 475, 486"},{"src":"brief","b":1,"text":"inquire into illegal detention with a view to an order releasing the petitioner.","cite":"411 U.S. 475, 484"},{"src":"brief","b":2,"text":"unlawfully confined in the wrong institution.","cite":"411 U.S. 475, 486"},{"src":"argument","who":"Ms. Hansford","text":"And it is materially indistinguishable from this Court's decision in Preiser against Rodriguez, which held that claims seeking release from prison to parole must be brought in habeas."},{"src":"argument","who":"Ms. Hansford","text":"I agree completely that whether something is distinct custody can raise hard questions, and this is an easy application of it, either by looking at a case like Preiser or by using the fact that it requires a change of custodian or by looking at the statutory scheme."},{"src":"argument","who":"Ms. Hansford","text":"The dispute is about the -- the number of good-time credits, and I do think this Court in Preiser and other cases has indicated that -- and in Wolff, for instance, as well that a challenge to the calculation to the number of good-time credits is a habeas claim on its own even if you are not asking for release, but Mr."}]},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"by":{"0":"29","1":"8"}},{"t":"case","label":"Rasul v. Bush","cite":"542 U.S. 466","y":2004,"id":"2003/03-334","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"Section 2241, by its terms, requires nothing more.","cite":"542 U.S. 466, 483-484"}]},{"t":"case","label":"RJR Nabisco v. European Community","cite":"579 U.S. 325","y":2016,"id":"2015/15-138","sc":1,"by":{"0":"29"}},{"t":"case","label":"Rodriguez v. McGinnis","cite":"307 F. Supp. 627","y":1969,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./307/627/","by":{"0":"25"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"by":{"0":"17, 32, 35","2":"10"},"q":[{"src":"brief","b":0,"text":"serves the important purpose of preventing forum shopping by habeas petitioners,","cite":"542 U.S. at 447"},{"src":"brief","b":2,"text":"contemplate[s] a proceeding against some person who has the immediate custody of the party detained.","cite":"542 U.S. 426, 435"}]},{"t":"case","label":"Samak v. Warden, FCC Coleman-Medium","cite":"766 F.3d 1271","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/766/1271/","by":{"0":"28","2":"18, 19"}},{"t":"case","label":"Schonbrun v. Commanding Officer, Armed Forces","cite":"403 F.2d 371","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/403/371/","by":{"0":"24"}},{"t":"case","label":"Seymore v. Beto","cite":"383 F.2d 384","y":1967,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/383/384/","by":{"0":"24"}},{"t":"case","label":"Skinner v. Switzer","cite":"562 U.S. 521","y":2011,"id":"2010/09-9000","sc":1,"by":{"0":"3, 27, 33","1":"24","2":"4, 6"},"q":[{"src":"brief","b":0,"text":"reduce the prisoner’s level of custody.","cite":"562 U.S. 521, 534"},{"src":"brief","b":1,"text":"to say that the habeas statute authorizes federal courts to order relief that neither terminates custody, accelerates the future date of release from custody, nor reduces the level of custody.","cite":"562 U.S. 521"},{"src":"argument","who":"Justice Kagan","text":"Coming from Justice Scalia's concurrence, gets picked up by the full Court in Skinner. Are -- are you rejecting that language? Would you have us reject that language, which we did use in Skinner?"},{"src":"argument","who":"Mr. Barber","text":"I don't think the Court has gone farther than that, certainly not in a holding, because, in Skinner, I mean, that case had nothing to do with levels of custody at all."},{"src":"argument","who":"Justice Kagan","text":"So you think that that language that we used in Skinner was too broad?"}]},{"t":"case","label":"Solida v. McKelvey","cite":"820 F.3d 1090","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/820/1090/","by":{"0":"30"}},{"t":"case","label":"Spencer v. Haynes","cite":"774 F.3d 467","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/774/467/","by":{"0":"30, 39"}},{"t":"case","label":"Storm v. United States Parole Commission","cite":"667 Fed. Appx. 156","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./667/156/","by":{"0":"36"}},{"t":"case","label":"Thomas v. Brennan","cite":"961 F.2d 612","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/961/612/","by":{"0":"24"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"606 U.S. 831","y":2025,"id":"2024/24a884","sc":1,"by":{"0":"31"}},{"t":"case","label":"Trump v. Cook","cite":"146 S. Ct. 2234","y":2026,"url":"https://www.courtlistener.com/c/S.%20Ct./146/2234/","sc":1,"by":{"0":"31"}},{"t":"case","label":"Trump v. J.G.G.","cite":"604 U.S. 670","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/670/","sc":1,"by":{"0":"18, 28, 29, 32","2":"5"},"q":[{"src":"brief","b":0,"text":"their claims for relief ‘necessarily imply the invalidity’","cite":"604 U.S. at 672"}]},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"by":{"0":"6, 33"}},{"t":"case","label":"United States v. Haymond","cite":"588 U.S. 634","y":2019,"id":"2018/17-1672","sc":1,"by":{"0":"7"}},{"t":"case","label":"United States v. Jones","cite":"752 F.3d 1039","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/752/1039/","by":{"0":"36"}},{"t":"case","label":"United States v. Scarfo","cite":"41 F.4th 136","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/41/136/","by":{"0":"9"}},{"t":"case","label":"Valladares v. Ray","cite":"130 F.4th 74","y":2025,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/130/74/","by":{"0":"9"}},{"t":"case","label":"Walker v. Wainwright","cite":"390 U.S. 335","y":1968,"id":"scdb/1967-079","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"another prison term might still await","cite":"390 U.S. 335, 336-337"}]},{"t":"case","label":"Wilkinson v. Dotson","cite":"544 U.S. 74","y":2005,"id":"2004/03-287","sc":1,"by":{"0":"3, 6, 18, 26, 27, 38","1":"3, 20, 23-26, 28, 34","2":"6, 7"},"q":[{"src":"brief","b":0,"text":"restoration of good-time credits, which would shorten the prisoners’ incarceration and hasten the date on which they would be transferred to supervised release * * * was available in habeas.","cite":"544 U.S. at 86"},{"src":"brief","b":0,"text":"the relief sought would ‘neither terminate custody, accelerate the future date of release from custody, nor reduce the level of custody.’","cite":"544 U.S. at 86"},{"src":"brief","b":1,"text":"act[] under color of state law.","cite":"544 U.S. 74, 87"},{"src":"brief","b":1,"text":"[i]t is one thing to say that permissible habeas relief, as our cases interpret the statute, includes ordering a ‘quantum change in the level of custody,’ such as release from incarceration to parole.","cite":"544 U.S. at 86"},{"src":"brief","b":2,"text":"considerations of linguistic specificity, history, and comity","cite":"544 U.S. at 79"}]},{"t":"case","label":"Woodall v. Federal Bureau of Prisons","cite":"432 F.3d 235","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/432/235/","by":{"0":"36","1":"31, 32"}},{"t":"case","label":"Page Case—continued: Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"url":"https://supreme.justia.com/cases/federal/us/582/120/","sc":1,"by":{"0":"30"}},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"0":"6","2":"18, 19"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":"13, 30, 31, 33","1":"21"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"7, 14, 32, 33","1":"19"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"9, 10, 11, 31, 34","1":"2, 8","2":"7-10, 17-19"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1987","by":{"0":"8","2":"13"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(b)","(b)(11)","(b)(19)"],"by":{"0":"9, 36, 36"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(a)","(d)","(e)(3)"],"by":{"0":"8, 8, 8, 9","1":"7, 8, 32"},"q":[{"src":"brief","b":1,"text":"all or part of the term of supervised release.","cite":"18 U.S.C. 3583(e)(3)"}]},{"t":"usc","label":"18 U.S.C. § 3624","url":"https://www.law.cornell.edu/uscode/text/18/3624","subs":["(c)","(c)(1)","(g)","(g)(2)(A)(i)","(g)(2)(A)(i)(II)","(g)(2)(B)","(g)(4)","(g)(5)","(a)","(b)(1)","(c)(2)","(c)(4)","(c)(5)","(g)(1)","(g)(1)(A)","(g)(1)(B)","(g)(2)","(g)(2)(A)","(g)(2)(A)(i)(I)","(g)(3)","(g)(10)","(g)(2)(A)(i)(II)(gg)"],"stext":{"head":"§3624. Release of a prisoner","paras":[[0,"(a) Date of Release.—A prisoner shall be released by the Bureau of Prisons on the date of the expiration of the prisoner's term of imprisonment, less any time credited toward the service of the prisoner's sentence as provided in subsection (b). If the date for a prisoner's release falls on a Saturday, a Sunday, or a legal holiday at the place of confinement, the prisoner may be released by the Bureau on the last preceding weekday."],[0,"(b) Credit Toward Service of Sentence for Satisfactory Behavior.—(1) Subject to paragraph (2), a prisoner who is serving a term of imprisonment of more than 1 year 1 other than a term of imprisonment for the duration of the prisoner's life, may receive credit toward the service of the prisoner's sentence of up to 54 days for each year of the prisoner's sentence imposed by the court, subject to determination by the Bureau of Prisons that, during that year, the prisoner has displayed exemplary compliance with institutional disciplinary regulations. Subject to paragraph (2), if the Bureau determines that, during that year, the prisoner has not satisfactorily complied with such institutional regulations, the prisoner shall receive no such credit toward service of the prisoner's sentence or shall receive such lesser credit as the Bureau determines to be appropriate. In awarding credit under this section, the Bureau shall consider whether the prisoner, during the relevant period, has earned, or is making satisfactory progress toward earning, a high school diploma or an equivalent degree. Credit that has not been earned may not later be granted. Subject to paragraph (2), credit for the last year of a term of imprisonment shall be credited on the first day of the last year of the term of imprisonment."],[0,"(2) Notwithstanding any other law, credit awarded under this subsection after the date of enactment of the Prison Litigation Reform Act shall vest on the date the prisoner is released from custody."],[0,"(3) The Attorney General shall ensure that the Bureau of Prisons has in effect an optional General Educational Development program for inmates who have not earned a high school diploma or its equivalent."],[0,"(4) Exemptions to the General Educational Development requirement may be made as deemed appropriate by the Director of the Federal Bureau of Prisons."],[0,"(c) Prerelease Custody.—"],[1,"(1) In general.—The Director of the Bureau of Prisons shall, to the extent practicable, ensure that a prisoner serving a term of imprisonment spends a portion of the final months of that term (not to exceed 12 months), under conditions that will afford that prisoner a reasonable opportunity to adjust to and prepare for the reentry of that prisoner into the community. Such conditions may include a community correctional facility."],[1,"(2) Home confinement authority.—The authority under this subsection may be used to place a prisoner in home confinement for the shorter of 10 percent of the term of imprisonment of that prisoner or 6 months. The Bureau of Prisons shall, to the extent practicable, place prisoners with lower risk levels and lower needs on home confinement for the maximum amount of time permitted under this paragraph."],[1,"(3) Assistance.—The United States Probation System shall, to the extent practicable, offer assistance to a prisoner during prerelease custody under this subsection."],[1,"(4) No limitations.—Nothing in this subsection shall be construed to limit or restrict the authority of the Director of the Bureau of Prisons under section 3621."],[1,"(5) Reporting.—Not later than 1 year after the date of the enactment of the Second Chance Act of 2007 (and every year thereafter), the Director of the Bureau of Prisons shall transmit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report describing the Bureau's utilization of community corrections facilities. Each report under this paragraph shall set forth the number and percentage of Federal prisoners placed in community corrections facilities during the preceding year, the average length of such placements, trends in such utilization, the reasons some prisoners are not placed in community corrections facilities, and number of prisoners not being placed in community corrections facilities for each reason set forth, and any other information that may be useful to the committees in determining if the Bureau is utilizing community corrections facilities in an effective manner."],[1,"(6) Issuance of regulations.—The Director of the Bureau of Prisons shall issue regulations pursuant to this subsection not later than 90 days after the date of the enactment of the Second Chance Reauthorization Act of 2018, which shall ensure that placement in a community correctional facility by the Bureau of Prisons is—"],[2,"(A) conducted in a manner consistent with section 3621(b) of this title;"],[2,"(B) determined on an individual basis; and"],[2,"(C) of sufficient duration to provide the greatest likelihood of successful reintegration into the community."],[0,"(d) Allotment of Clothing, Funds, and Transportation.—Upon the release of a prisoner on the expiration of the prisoner's term of imprisonment, the Bureau of Prisons shall furnish the prisoner with—"],[1,"(1) suitable clothing;"],[1,"(2) an amount of money, not more than $500, determined by the Director to be consistent with the needs of the offender and the public interest, unless the Director determines that the financial position of the offender is such that no sum should be furnished; and"],[1,"(3) transportation to the place of the prisoner's conviction, to the prisoner's bona fide residence within the United States, or to such other place within the United States as may be authorized by the Director."],[0,"(e) Supervision After Release.—A prisoner whose sentence includes a term of supervised release after imprisonment shall be released by the Bureau of Prisons to the supervision of a probation officer who shall, during the term imposed, supervise the person released to the degree warranted by the conditions specified by the sentencing court. The term of supervised release commences on the day the person is released from imprisonment and runs concurrently with any Federal, State, or local term of probation or supervised release or parole for another offense to which the person is subject or becomes subject during the term of supervised release. A term of supervised release does not run during any period in which the person is imprisoned in connection with a conviction for a Federal, State, or local crime unless the imprisonment is for a period of less than 30 consecutive days. Upon the release of a prisoner by the Bureau of Prisons to supervised release, the Bureau of Prisons shall notify such prisoner, verbally and in writing, of the requirement that the prisoner adhere to an installment schedule, not to exceed 2 years except in special circumstances, to pay for any fine imposed for the offense committed by such prisoner, and of the consequences of failure to pay such fines under sections 3611 through 3614 of this title."],[0,"(f) Mandatory Functional Literacy Requirement.—"],[1,"(1) The Attorney General shall direct the Bureau of Prisons to have in effect a mandatory functional literacy program for all mentally capable inmates who are not functionally literate in each Federal correctional institution within 6 months from the date of the enactment of this Act."],[1,"(2) Each mandatory functional literacy program shall include a requirement that each inmate participate in such program for a mandatory period sufficient to provide the inmate with an adequate opportunity to achieve functional literacy, and appropriate incentives which lead to successful completion of such programs shall be developed and implemented."],[1,"(3) As used in this section, the term \"functional literacy\" means—"],[2,"(A) an eighth grade equivalence in reading and mathematics on a nationally recognized standardized test;"],[2,"(B) functional competency or literacy on a nationally recognized criterion-referenced test; or"],[2,"(C) a combination of subparagraphs (A) and (B)."],[1,"(4) Non-English speaking inmates shall be required to participate in an English-As-A-Second-Language program until they function at the equivalence of the eighth grade on a nationally recognized educational achievement test."],[1,"(5) The Chief Executive Officer of each institution shall have authority to grant waivers for good cause as determined and documented on an individual basis."],[0,"(g) Prerelease Custody or Supervised Release for Risk and Needs Assessment System Participants.—"],[1,"(1) Eligible prisoners.—This subsection applies in the case of a prisoner (as such term is defined in section 3635) who—"],[2,"(A) has earned time credits under the risk and needs assessment system developed under subchapter D (referred to in this subsection as the \"System\") in an amount that is equal to the remainder of the prisoner's imposed term of imprisonment;"],[2,"(B) has shown through the periodic risk reassessments a demonstrated recidivism risk reduction or has maintained a minimum or low recidivism risk, during the prisoner's term of imprisonment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3624?type=usc&year=mostrecent&link-type=html"},"by":{"0":"8, 9, 34, 34, 9, 14, 34, 36, 34, 34, 34, 35","1":"20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20, 20","2":"9, 3, 13, 17, 18, 9, 18, 11, 9, 11, 9, 13"},"q":[{"src":"brief","b":1,"text":"display[ing] exemplary compliance with institutional disciplinary regulations,","cite":"18 U.S.C. 3624(b)(1)"},{"src":"brief","b":1,"text":"the shorter of 10 percent of the term of imprisonment of that prisoner or 6 months.","cite":"18 U.S.C. 3624(c)(2)"}]},{"t":"usc","label":"18 U.S.C. § 3625","url":"https://www.law.cornell.edu/uscode/text/18/3625","by":{"0":"31","1":"20"}},{"t":"usc","label":"18 U.S.C. § 3632","url":"https://www.law.cornell.edu/uscode/text/18/3632","subs":["(d)","(d)(4)(A)","(d)(4)(C)","(a)(3)","(d)(1)","(d)(4)(A)(i)","(d)(4)(D)","(d)(4)"],"stext":{"head":"§3632. Development of risk and needs assessment system","paras":[[0,"(a) In General.—Not later than 210 days after the date of enactment of this subchapter, the Attorney General, in consultation with the Independent Review Committee authorized by the First Step Act of 2018, shall develop and release publicly on the Department of Justice website a risk and needs assessment system (referred to in this subchapter as the \"System\"), which shall be used to—"],[1,"(1) determine the recidivism risk of each prisoner as part of the intake process, and classify each prisoner as having minimum, low, medium, or high risk for recidivism;"],[1,"(2) assess and determine, to the extent practicable, the risk of violent or serious misconduct of each prisoner;"],[1,"(3) determine the type and amount of evidence-based recidivism reduction programming that is appropriate for each prisoner and assign each prisoner to such programming accordingly, and based on the prisoner's specific criminogenic needs, and in accordance with subsection (b);"],[1,"(4) reassess the recidivism risk of each prisoner periodically, based on factors including indicators of progress, and of regression, that are dynamic and that can reasonably be expected to change while in prison;"],[1,"(5) reassign the prisoner to appropriate evidence-based recidivism reduction programs or productive activities based on the revised determination to ensure that—"],[2,"(A) all prisoners at each risk level have a meaningful opportunity to reduce their classification during the period of incarceration;"],[2,"(B) to address 1 the specific criminogenic needs of the prisoner; and"],[2,"(C) all prisoners are able to successfully participate in such programs;"],[1,"(6) determine when to provide incentives and rewards for successful participation in evidence-based recidivism reduction programs or productive activities in accordance with subsection (e);"],[1,"(7) determine when a prisoner is ready to transfer into prerelease custody or supervised release in accordance with section 3624; and"],[1,"(8) determine the appropriate use of audio technology for program course materials with an understanding of dyslexia."],[0,"In carrying out this subsection, the Attorney General may use existing risk and needs assessment tools, as appropriate."],[0,"(b) Assignment of Evidence-based Recidivism Reduction Programs.—The System shall provide guidance on the type, amount, and intensity of evidence-based recidivism reduction programming and productive activities that shall be assigned for each prisoner, including—"],[1,"(1) programs in which the Bureau of Prisons shall assign the prisoner to participate, according to the prisoner's specific criminogenic needs; and"],[1,"(2) information on the best ways that the Bureau of Prisons can tailor the programs to the specific criminogenic needs of each prisoner so as to most effectively lower each prisoner's risk of recidivism."],[0,"(c) Housing and Assignment Decisions.—The System shall provide guidance on program grouping and housing assignment determinations and, after accounting for the safety of each prisoner and other individuals at the prison, provide that prisoners with a similar risk level be grouped together in housing and assignment decisions to the extent practicable."],[0,"(d) Evidence-Based Recidivism Reduction Program Incentives and Productive Activities Rewards.—The System shall provide incentives and rewards for prisoners to participate in and complete evidence-based recidivism reduction programs as follows:"],[1,"(1) Phone and visitation privileges.—A prisoner who is successfully participating in an evidence-based recidivism reduction program shall receive—"],[2,"(A) phone privileges, or, if available, video conferencing privileges, for up to 30 minutes per day, and up to 510 minutes per month; and"],[2,"(B) additional time for visitation at the prison, as determined by the warden of the prison."],[1,"(2) Transfer to institution closer to release residence.—A prisoner who is successfully participating in an evidence-based recidivism reduction program shall be considered by the Bureau of Prisons for placement in a facility closer to the prisoner's release residence upon request from the prisoner and subject to—"],[2,"(A) bed availability at the transfer facility;"],[2,"(B) the prisoner's security designation; and"],[2,"(C) the recommendation from the warden of the prison at which the prisoner is incarcerated at the time of making the request."],[1,"(3) Additional policies.—The Director of the Bureau of Prisons shall develop additional policies to provide appropriate incentives for successful participation and completion of evidence-based recidivism reduction programming. The incentives shall include not less than 2 of the following:"],[2,"(A) Increased commissary spending limits and product offerings."],[2,"(B) Extended opportunities to access the email system."],[2,"(C) Consideration of transfer to preferred housing units (including transfer to different prison facilities)."],[2,"(D) Other incentives solicited from prisoners and determined appropriate by the Director."],[1,"(4) Time credits.—"],[2,"(A) In general.—A prisoner, except for an ineligible prisoner under subparagraph (D), who successfully completes evidence-based recidivism reduction programming or productive activities, shall earn time credits as follows:"],[3,"(i) A prisoner shall earn 10 days of time credits for every 30 days of successful participation in evidence-based recidivism reduction programming or productive activities."],[3,"(ii) A prisoner determined by the Bureau of Prisons to be at a minimum or low risk for recidivating, who, over 2 consecutive assessments, has not increased their risk of recidivism, shall earn an additional 5 days of time credits for every 30 days of successful participation in evidence-based recidivism reduction programming or productive activities."],[2,"(B) Availability.—A prisoner may not earn time credits under this paragraph for an evidence-based recidivism reduction program that the prisoner successfully completed—"],[3,"(i) prior to the date of enactment of this subchapter; or"],[3,"(ii) during official detention prior to the date that the prisoner's sentence commences under section 3585(a)."],[2,"(C) Application of time credits toward prerelease custody or supervised release.—Time credits earned under this paragraph by prisoners who successfully participate in recidivism reduction programs or productive activities shall be applied toward time in prerelease custody or supervised release. The Director of the Bureau of Prisons shall transfer eligible prisoners, as determined under section 3624(g), into prerelease custody or supervised release."],[2,"(D) Ineligible prisoners.—A prisoner is ineligible to receive time credits under this paragraph if the prisoner is serving a sentence for a conviction under any of the following provisions of law:"],[3,"(i) Section 32, relating to destruction of aircraft or aircraft facilities."],[3,"(ii) Section 33, relating to destruction of motor vehicles or motor vehicle facilities."],[3,"(iii) Section 36, relating to drive-by shootings."],[3,"(iv) Section 81, relating to arson within special maritime and territorial jurisdiction."],[3,"(v) Section 111(b), relating to assaulting, resisting, or impeding certain officers or employees using a deadly or dangerous weapon or inflicting bodily injury."],[3,"(vi) Paragraph (1), (7), or (8) of section 113(a), relating to assault with intent to commit murder, assault resulting in substantial bodily injury to a spouse or intimate partner, a dating partner, or an individual who has not attained the age of 16 years, or assault of a spouse, intimate partner, or dating partner by strangling, suffocating, or attempting to strangle or suffocate."],[3,"(vii) Section 115, relating to influencing, impeding, or retaliating against a Federal official by injuring a family member, except for a threat made in violation of that section."],[3,"(viii) Section 116, relating to female genital mutilation."],[3,"(ix) Section 117, relating to domestic assault by a habitual offender."],[3,"(x) Any section of chapter 10, relating to biological weapons."],[3,"(xi) Any section of chapter 11B, relating to chemical weapons."],[3,"(xii) Section 351, relating to Congressional, Cabinet, and Supreme Court assassination, kidnapping, and assault."],[3,"(xiii) Section 521, relating to criminal street gangs."],[3,"(xiv) Section 751, relating to prisoners in custody of an institution or officer."],[3,"(xv) Section 793, relating to gathering, transmitting, or losing defense information."],[3,"(xvi) Section 794, relating to gathering or delivering defense information to aid a foreign government."],[3,"(xvii) Any section of chapter 39, relating to explosives and other dangerous articles, except for section 836 (relating to the transportation of fireworks into a State prohibiting sale or use)."],[3,"(xviii) Section 842(p), relating to distribution of information relating to explosives, destructive devices, and weapons of mass destruction, but only if the conviction involved a weapon of mass destruction (as defined in section 2332a(c))."],[3,"(xix) Subsection (f)(3), (h), or (i) of section 844, relating to the use of fire or an explosive."],[3,"(xx) Section 871, relating to threats against the President and successors to the Presidency."],[3,"(xxi) Section 879, relating to threats against former Presidents and certain other persons."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3632?type=usc&year=mostrecent&link-type=html"},"by":{"0":"9, 9, 10, 14, 9","1":"20, 20, 20, 20, 20","2":"18, 3, 17, 18"},"q":[{"src":"brief","b":0,"text":"into prerelease custody or supervised release.","cite":"18 U.S.C. 3632(d)(4)(C)"},{"src":"brief","b":1,"text":"earn[s] 10 days of time credits for every 30 days of successful participation in evidence-based recidivism reduction programming or productive activities.","cite":"18 U.S.C. 3632(d)(4)(A)(i)"},{"src":"brief","b":1,"text":"shall transfer eligible prisoners, as determined under [18 U.S.C.] 3624(g).","cite":"18 U.S.C. 3632(d)(4)(C)"},{"src":"brief","b":2,"text":"shall transfer eligible prisoners, as determined under section 3624(g), into prerelease custody or supervised release.","cite":"18 U.S.C. 3632(d)(4)(C)"}]},{"t":"usc","label":"18 U.S.C. § 3635","url":"https://www.law.cornell.edu/uscode/text/18/3635","subs":["(3)","(5)","(3)(C)(iii)","(3)(C)(v)","(3)(C)(ix)"],"by":{"0":"10, 10","1":"20, 20, 20"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/28/1361","by":{"0":"31","1":"20"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","subs":["(e)(1)"],"by":{"0":"33"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","subs":["(1994)","(a)","(c)","(c)(3)"],"stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 2, 7, 10-12, 4, 16, 19, 4, 16","1":"18, 22","2":"4, 5, 9"},"q":[{"src":"brief","b":0,"text":"dispose of the matter as law and justice require.","cite":"28 U.S.C. 2241(a)"},{"src":"brief","b":0,"text":"is in custody in violation of the Constitution or laws or treaties of the United States.","cite":"28 U.S.C. 2241(a)"},{"src":"brief","b":1,"text":"largely recodified the federal courts’ pre-existing habeas authority","cite":"28 U.S.C. 2241"},{"src":"brief","b":2,"text":"dispose of the matter as law and justice require.","cite":"28 U.S.C. 2241, 2243"}]},{"t":"usc","label":"28 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/28/2243","subs":["(1994)"],"stext":{"head":"§2243. Issuance of writ; return; hearing; decision","paras":[[0,"A court, justice or judge entertaining an application for a writ of habeas corpus shall forthwith award the writ or issue an order directing the respondent to show cause why the writ should not be granted, unless it appears from the application that the applicant or person detained is not entitled thereto."],[0,"The writ, or order to show cause shall be directed to the person having custody of the person detained. It shall be returned within three days unless for good cause additional time, not exceeding twenty days, is allowed."],[0,"The person to whom the writ or order is directed shall make a return certifying the true cause of the detention."],[0,"When the writ or order is returned a day shall be set for hearing, not more than five days after the return unless for good cause additional time is allowed."],[0,"Unless the application for the writ and the return present only issues of law the person to whom the writ is directed shall be required to produce at the hearing the body of the person detained."],[0,"The applicant or the person detained may, under oath, deny any of the facts set forth in the return or allege any other material facts."],[0,"The return and all suggestions made against it may be amended, by leave of court, before or after being filed."],[0,"The court shall summarily hear and determine the facts, and dispose of the matter as law and justice require."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2243?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 2, 4, 7, 12, 16-19, 24","1":"18, 22","2":"4"},"q":[{"src":"brief","b":0,"text":"shall * * * dispose of the matter as law and justice require.","cite":"28 U.S.C. 2243"},{"src":"brief","b":0,"text":"dispose of the matter as law and justice require.","cite":"28 U.S.C. 2243"}]},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)","(d)(1)"],"by":{"0":"7, 32, 33","1":"18"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(1994)","(b)","(d)"],"by":{"0":"7, 32, 7, 33","1":"22","2":"15"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(1994)","(a)","(e)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 3, 7, 16, 18, 24, 18, 12, 19, 27","1":"18, 18","2":"3, 5, 5"},"q":[{"src":"brief","b":0,"text":"appears that the remedy by motion is inadequate or ineffective to test the legality of his detention.","cite":"28 U.S.C. 2255(e)"},{"src":"brief","b":1,"text":"the court which imposed the sentence.","cite":"28 U.S.C. 2255(a)"}]},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 14, 25-27, 30, 33","1":"28","2":"2, 8, 15"},"q":[{"src":"argument","who":"Mr. Barber","text":"That's why those claims were allowed to proceed under Section 1983. But we don't think that you've wedded yourself to the kind of open-ended, amorphous level-of-custody test that Petitioner seemed to advance in his briefs."}]},{"t":"case","label":"Albright v. Oliver","cite":"510 U.S. 266","y":1994,"id":"1993/92-833","sc":1,"by":{"1":"29"}},{"t":"case","label":"Anderson v. Corall","cite":"263 U.S. 193","y":1923,"id":"scdb/1923-028","sc":1,"by":{"1":"7, 27","2":"10"}},{"t":"case","label":"Baxter v. Bracey","cite":"590 U.S. 1011","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/1011/","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"a statute variously known as the Ku Klux Act of 1871, the Civil Rights Act of 1871, and the Enforcement Act of 1871,","cite":"590 U.S. 1011, 1012"}]},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"by":{"1":"20, 33"}},{"t":"case","label":"Carson v. Johnson","cite":"112 F.3d 818","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/818/","by":{"1":"33"}},{"t":"case","label":"Conway v. California Adult Auth.","cite":"396 U.S. 107","y":1969,"id":"1969/40","sc":1,"by":{"1":"41"}},{"t":"case","label":"Cooper v. Pate","cite":"378 U.S. 546","y":1964,"id":"scdb/1963-172","sc":1,"by":{"1":"19"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"a court of review, not of first view.","cite":"544 U.S. 709, 718 n.7"}]},{"t":"case","label":"DHS v. Thuraissigiam","cite":"591 U.S. 103","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/103/","sc":1,"by":{"1":"29, 39"},"q":[{"src":"brief","b":1,"text":"would have been unrecognizable at that time.","cite":"591 U.S. at 107"}]},{"t":"case","label":"Davis v. Passman","cite":"442 U.S. 228","y":1979,"id":"1978/78-5072","sc":1,"by":{"1":"33"}},{"t":"case","label":"Dreyer v. Illinois","cite":"187 U.S. 71","y":1902,"id":"scdb/1902-031","sc":1,"by":{"1":"28"}},{"t":"case","label":"E.M.D. Sales, Inc. v. Carrera","cite":"604 U.S. 45","y":2025,"id":"2024/23-217","sc":1,"by":{"1":"40","2":"16"},"q":[{"src":"brief","b":2,"text":"leave matters of that sort for remand.","cite":"604 U.S. 45, 54"}]},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"by":{"1":"17, 19"}},{"t":"case","label":"Esteras v. United States","cite":"606 U.S. 185","y":2025,"id":"2024/23-7483","sc":1,"by":{"1":"7, 38"},"q":[{"src":"brief","b":1,"text":"Supervised release is a form of postconfinement monitoring that permits a defendant a kind of conditional liberty by allowing him to serve part of his sentence outside of prison, subject to conditions on his behavior.","cite":"606 U.S. 185, 192"}]},{"t":"case","label":"Graham v. Broglin","cite":"922 F.2d 379","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/922/379/","by":{"1":"24, 26","2":"6"},"q":[{"src":"brief","b":1,"text":"reduction in the level of custody","cite":"922 F.2d at 381"}]},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"by":{"1":"21"}},{"t":"case","label":"Hernández v. Mesa","cite":"589 U.S. 93","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/93/","sc":1,"by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"broke new ground by holding that a person claiming to be the victim of an unlawful arrest and search could bring a Fourth Amendment claim for damages against the responsible agents even though no federal statute authorized such a claim.","cite":"589 U.S. 93, 99"}]},{"t":"case","label":"Hewitt v. United States","cite":"606 U.S. 419","y":2025,"id":"2024/23-1002","sc":1,"by":{"1":"8"}},{"t":"case","label":"Ingram v. SCI Smithfield","cite":"2023 WL 110588","y":2023,"court":"3d Cir. Jan. 5","by":{"1":"34"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"by":{"1":"7","2":"10"}},{"t":"case","label":"Kansas v. Garcia","cite":"589 U.S. 191","y":2020,"id":"2019/17-834","sc":1,"by":{"1":"39"}},{"t":"case","label":"McInnis v. Strand","cite":"2008 WL 2206712","y":2008,"court":"D.N.D. May 27","by":{"1":"34"}},{"t":"case","label":"McKune v. Lile","cite":"536 U.S. 24","y":2002,"id":"2001/00-1187","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"It is well settled that the decision where to house inmates is at the core of prison administrators’ expertise.","cite":"536 U.S. 24, 39"}]},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"by":{"1":"30, 31"},"q":[{"src":"brief","b":1,"text":"conditions [that] restrict their activities substantially beyond the ordinary restrictions imposed by law on an individual citizen.","cite":"408 U.S. 471, 478"},{"src":"brief","b":1,"text":"gainfully employed and * * * free to be with family and friends and to form the other enduring attachments of normal life.","cite":"408 U.S. at 482"},{"src":"argument","who":"Mr. Barber","text":"So, in Morrissey against Brewer, it said the essence of parole is release from prison before the completion of sentence on the condition that the prisoner abide by certain rules during the balance of the sentence."}]},{"t":"case","label":"Muhammad v. Close","cite":"540 U.S. 749","y":2004,"id":"2003/02-9065","sc":1,"by":{"1":"21, 22","2":"8, 15"},"q":[{"src":"brief","b":1,"text":"requests for relief turning on circumstances of confinement may be presented in a § 1983 action.","cite":"540 U.S. 749, 750"}]},{"t":"case","label":"Mullin v. Doe","cite":"146 S. Ct. 2121","y":2026,"id":"2025/25-1083","sc":1,"by":{"1":"36"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"1":"38"}},{"t":"case","label":"Nettles v. Grounds","cite":"830 F.3d 922","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/830/922/","by":{"1":"36","2":"7"}},{"t":"case","label":"Osorio-Calderon v. Warden","cite":"179 F.4th 1158","y":2026,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/179/1158/","by":{"1":"39, 40"},"q":[{"src":"argument","who":"Mr. Barber","text":"So you have, in the Osorio-Calderon case from the Eighth Circuit that we cite in our brief, the situation there was that the prisoner was a sex offender."}]},{"t":"case","label":"People v. Santos","cite":"298 N.Y.S.2d 526","y":1969,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/298/526/","by":{"1":"28"}},{"t":"case","label":"Perttu v. Richards","cite":"605 U.S. 460","y":2025,"id":"2024/23-1324","sc":1,"by":{"1":"16, 20","2":"19"},"q":[{"src":"brief","b":1,"text":"Our legal system is committed to guaranteeing that prisoner claims of illegal conduct by their custodians are fairly handled according to law.","cite":"605 U.S. 460, 464"},{"src":"argument","who":"Ms. Hansford","text":"Maxwell has also raised problems of obstruction of the process and has asserted a right under Perttu to a jury trial related to those. But those are the three arguments on exhaustion that we would like to make on remand."}]},{"t":"case","label":"Piccarillo v. New York State Bd. of Parole","cite":"397 N.E.2d 354","y":1979,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/397/354/","by":{"1":"28"}},{"t":"case","label":"Porter v. Nussle","cite":"534 U.S. 516","y":2002,"id":"2001/00-853","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"Ordinarily, plaintiffs pursuing civil rights claims under 42 U.S.C. § 1983 need not exhaust administrative remedies before filing suit in court.","cite":"534 U.S. 516, 523"}]},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"by":{"1":"27","2":"12"}},{"t":"case","label":"Sanchez v. Miller","cite":"792 F.2d 694","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/792/694/","by":{"1":"35"}},{"t":"case","label":"Samson v. California","cite":"547 U.S. 843","y":2006,"id":"2005/04-9728","sc":1,"by":{"1":"27"}},{"t":"case","label":"Stanley v. City of Sanford","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"Legislation is, after all, the art of compromise, the limitations expressed in statutory terms often the price of passage, and no statute yet known pursues its stated purpose at all costs.","cite":"606 U.S. 46, 58"}]},{"t":"case","label":"Sylvester v. Hanks","cite":"140 F.3d 713","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/140/713/","by":{"1":"26"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"by":{"1":"36"}},{"t":"case","label":"Touzier v. United States Att’y Gen.","cite":"2021 WL 3829618","y":2021,"court":"11th Cir. Aug. 27","by":{"1":"39"}},{"t":"case","label":"Trainmen v. Toledo, Peoria & W. R.R.","cite":"321 U.S. 50","y":1944,"id":"scdb/1943-097","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"plenary control over the jurisdiction of the federal courts.","cite":"321 U.S. 50, 63-64"}]},{"t":"case","label":"Ughbanks v. Armstrong","cite":"208 U.S. 481","y":1908,"id":"scdb/1907-090","sc":1,"by":{"1":"28"}},{"t":"case","label":"United States v. Anderson","cite":"583 F.3d 504","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/583/504/","by":{"1":"31"}},{"t":"case","label":"United States v. Earl","cite":"729 F.3d 1064","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/1064/","by":{"1":"27"}},{"t":"case","label":"United States v. Holt","cite":"116 F.4th 599","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/116/599/","by":{"1":"21"}},{"t":"case","label":"United States v. Latimer","cite":"991 F.2d 1509","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/991/1509/","by":{"1":"31"}},{"t":"case","label":"United States v. Muniz","cite":"374 U.S. 150","y":1963,"id":"1962/464","sc":1,"by":{"1":"20"}},{"t":"case","label":"United States v. Price","cite":"84 F.4th 738","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/84/738/","by":{"1":"5"}},{"t":"case","label":"United States v. Sack","cite":"379 F.3d 1177","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/379/1177/","by":{"1":"29"}},{"t":"case","label":"Upper Skagit Indian Tribe v. Lundgren","cite":"584 U.S. 554","y":2018,"id":"2017/17-387","sc":1,"by":{"1":"40"}},{"t":"case","label":"Warden v. Marrero","cite":"417 U.S. 653","y":1974,"id":"1973/73-831","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"even with its legal constraints—is a long step toward regaining lost freedom.","cite":"417 U.S. 653, 663"}]},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"account[ed] for an outsized share of filings","cite":"548 U.S. 81, 94 n.4"}]},{"t":"case","label":"Wolff v. McDonnell","cite":"418 U.S. 539","y":1974,"id":"1973/73-679","sc":1,"by":{"1":"23"},"q":[{"src":"argument","who":"Ms. Hansford","text":"The dispute is about the -- the number of good-time credits, and I do think this Court in Preiser and other cases has indicated that -- and in Wolff, for instance, as well that a challenge to the calculation to the number of good-time credits is a habeas claim on its own even if you are not asking for release, but Mr."}]},{"t":"case","label":"Young v. Harper","cite":"520 U.S. 143","y":1997,"id":"1996/95-1598","sc":1,"by":{"1":"32","2":"13"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"1":"36"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"21"}},{"t":"law","label":"Coronavirus Aid, Relief, and Economic Security Act, Pub. L. No. 116-136","url":"https://www.govinfo.gov/link/plaw/116/public/136","by":{"1":"12"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)","(b)(1)"],"by":{"1":"20, 34"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)"],"by":{"1":"20, 20","2":"15"},"q":[{"src":"brief","b":1,"text":"with respect to prison conditions under section 1983 * * * or any other Federal law,","cite":"42 U.S.C. 1997e(a)"}]},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(d)"],"by":{"1":"3"}},{"t":"law","label":"Pub. L. No. 110-199","url":"https://www.govinfo.gov/link/plaw/110/public/199","by":{"1":"6"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"1":"3, 4"}},{"t":"usc","label":"18 U.S.C. § 751","url":"https://www.law.cornell.edu/uscode/text/18/751","by":{"1":"29"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(d)(1)","(d)(1)(2006)"],"by":{"1":"11, 4"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1512","url":"https://www.law.cornell.edu/uscode/text/18/1512","subs":["(k)"],"by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(h)"],"by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","subs":["(c)(1)(B)(i)"],"by":{"1":"29"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)"],"by":{"1":"7"}},{"t":"usc","label":"18 U.S.C. § 3621","url":"https://www.law.cornell.edu/uscode/text/18/3621","subs":["(a)","(b)","(b)(1)","(b)(4)(B)","(c)","(g)(2)","(g)(4)","(h)(5)(C)(iv)"],"by":{"1":"6, 34, 37, 37, 37, 37, 37, 20, 29","2":"3, 11, 15-19, 10"},"q":[{"src":"brief","b":1,"text":"until the expiration of the term imposed.","cite":"18 U.S.C. 3621(a)"},{"src":"brief","b":1,"text":"[n]otwithstanding any other provision of law, a designation of a place of imprisonment under this subsection is not reviewable by any court.","cite":"18 U.S.C. 3621(b)"}]},{"t":"case","label":"Adepoju v. Scales","cite":"782 F. Supp. 3d 306","y":2025,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/782/306/","by":{"2":"17"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"by":{"2":"20, 21"},"q":[{"src":"brief","b":2,"text":"a legally cognizable interest in the outcome.","cite":"568 U.S. 85, 91"},{"src":"brief","b":2,"text":"formidable burden of showing that it is absolutely clear the allegedly wrongful behavior could not reasonably be expected to recur.","cite":"568 U.S. at 91"}]},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"by":{"2":"15"}},{"t":"case","label":"Chafin v. Chafin","cite":"568 U.S. 165","y":2013,"id":"2012/11-1347","sc":1,"by":{"2":"21"},"q":[{"src":"argument","who":"Ms. Hansford","text":"Under Chafin versus Chafin, the question is just whether it's not in a substantial argument. It's plainly not in a substantial argument. So a live controversy will remain."},{"src":"argument","who":"Ms. Hansford","text":"And I don't think it's moot for the reason we said here, the Chafin versus Chafin reason, and potentially voluntary cessation. You know, to the extent you had any doubts about mootness in the event Mr."}]},{"t":"case","label":"Chatrie v. United States","cite":"609 U.S. 605","y":2026,"id":"2025/25-112","sc":1,"by":{"2":"19"}},{"t":"case","label":"Cooper Industries, Inc. v. Aviall Services, Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"by":{"2":"8"}},{"t":"case","label":"Gonzalez v. Herrera","cite":"151 F.4th 1076","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/151/1076/","by":{"2":"20, 21"}},{"t":"case","label":"Haines v. Kerner","cite":"404 U.S. 519","y":1972,"id":"1971/70-5025","sc":1,"by":{"2":"8, 15"}},{"t":"case","label":"(I) Cases—continued: INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"both the strong presumption in favor of judicial review of administrative action and the longstanding rule requiring a clear statement of congressional intent to repeal habeas jurisdiction.","cite":"533 U.S. 289, 298"}]},{"t":"case","label":"Meachum v. Fano","cite":"427 U.S. 215","y":1976,"id":"1975/75-252","sc":1,"by":{"2":"8"},"q":[{"src":"brief","b":2,"text":"within the normal limits or range of custody","cite":"427 U.S. at 225"},{"src":"argument","who":"Mr. Barnes","text":"The -- the Meachum case rejects the due process claim. But what I would say is there is a -- I think this Court's cases do recognize a due process interest in not having one's parole stripped, being pulled back from parole or pulled back from supervised release without due process."},{"src":"argument","who":"Mr. Barnes","text":"Unfortunately, I don't -- I'm not sure I have an answer to the question, but it -- it -- it may be that the government's always going to win in those inter-prison transfer cases because of the Meachum decision because there's not a statute that arguably entitles prisoners to be moved from one prison to another."}]},{"t":"case","label":"Ramsey v. Brennan","cite":"878 F.2d 995","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/878/995/","by":{"2":"12"}},{"t":"case","label":"Sinochem International Co. v. Malaysia International Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"by":{"2":"20"},"q":[{"src":"argument","who":"Mr. Barnes","text":"Under Sinochem, you can -- the Court can choose the order in which it decides jurisdictional issues. I -- I'm hard-pressed to see a strong argument that once Mr."}]},{"t":"case","label":"Wales v. Whitney","cite":"114 U.S. 564","y":1885,"id":"scdb/1884-238","sc":1,"by":{"2":"10"}},{"t":"case","label":"Warner Chappell Music, Inc. v. Nealy","cite":"601 U.S. 366","y":2024,"id":"2023/22-1078","sc":1,"by":{"2":"19"}},{"t":"case","label":"West Virginia v. B. P. J.","cite":"146 S. Ct. 2356","y":2026,"id":"2025/24-43","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"post-certiorari actions that would insulate a decision from review * * * must be viewed with a critical eye.","cite":"146 S. Ct. 2356, 2373 n.3"}]},{"t":"case","label":"Wright v. Cuyler","cite":"624 F.2d 455","y":1980,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/624/455/","by":{"2":"6"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 1761","url":"https://www.law.cornell.edu/uscode/text/18/1761","subs":["(a)"],"by":{"2":"10"}},{"t":"usc","label":"18 U.S.C. § 3585","url":"https://www.law.cornell.edu/uscode/text/18/3585","subs":["(b)"],"by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 4042","url":"https://www.law.cornell.edu/uscode/text/18/4042","subs":["(b)"],"by":{"2":"10"}},{"t":"usc","label":"18 U.S.C. § 4202","url":"https://www.law.cornell.edu/uscode/text/18/4202","subs":["(1982)"],"by":{"2":"13"}},{"t":"usc","label":"18 U.S.C. § 4205","url":"https://www.law.cornell.edu/uscode/text/18/4205","subs":["(1982)"],"by":{"2":"13"}},{"t":"usc","label":"18 U.S.C. § 4209","url":"https://www.law.cornell.edu/uscode/text/18/4209","subs":["(1982)"],"by":{"2":"13"}},{"t":"usc","label":"18 U.S.C. § 4214","url":"https://www.law.cornell.edu/uscode/text/18/4214","subs":["(1982)"],"by":{"2":"13"}},{"t":"reg","label":"28 C.F.R. § 2.52","url":"https://www.ecfr.gov/current/title-28/section-2.52","by":{"2":"13"}}]};